#include <northbridge/intel/i945/raminit.h>
#include <string.h>

/*
 * The Apple TV 1st gen has no SPD EEPROM; the DRAM is soldered and Apple
 * stored the timings in the flash "MemoryConfig" variable instead.
 *
 * Nanya NT5TU32M16BG-3C: DDR2-667 5-5-5, 512 Mb, 32M x 16, 4 banks,
 * A0-A12 rows / A0-A9 columns, 8192 refresh, burst 4/8, SSTL-1.8,
 * tAC 0.45 ns.  Four devices make the board's single 256 MB rank on a
 * 64-bit channel.  Generated by atv/spdgen.py in the qemu-atv tree;
 * byte 63 is sum(bytes 0..62) and bytes 64..127 are unused.
 */
static const u8 atv1_spd[128] = {
	0x80, 0x08, 0x08, 0x0d, 0x0a, 0x00, 0x40, 0x00,	/* 00 */
	0x05, 0x30, 0x45, 0x00, 0x82, 0x10, 0x00, 0x00,	/* 08 */
	0x0c, 0x04, 0x1c, 0x00, 0x02, 0x00, 0x00, 0x38,	/* 10 */
	0x45, 0x50, 0x45, 0x3c, 0x1e, 0x3c, 0x2d, 0x40,	/* 18 */
	0x00, 0x00, 0x40, 0x40, 0x3c, 0x28, 0x1e, 0x00,	/* 20 */
	0x00, 0x3c, 0x69, 0x80, 0x14, 0x14, 0x00, 0x00,	/* 28 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 30 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x12, 0x97,	/* 38 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 40 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 48 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 50 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 58 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 60 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 68 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 70 */
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,	/* 78 */
};

int mainboard_get_spd(int socket, u8 *raw_spd, size_t len)
{
	if (socket != 0 || len < sizeof(atv1_spd))
		return 0;

	memcpy(raw_spd, atv1_spd, sizeof(atv1_spd));
	return sizeof(atv1_spd);
}
